# Page 9: complete visible module/service/dataset code lists.
modules=json.loads((ROOT/'data/modules.json').read_text())
module_items=[]
for m in modules:
    if m['id']=='ai': continue
    name=m['name']
    if m['id']=='18': name='Queue & tokens in this script; public catalogue: Agency service facilitation'
    if m['id']=='19': name='Configuration console; users, roles & permissions'
    module_items.append(('SM-'+m['id'],name+'.'))
services=[(r['service_code'],e(r['service_name'])+'.') for r in rows('M04_Services')]
sheets=[('M01','Districts'),('M02','ILAC centres'),('M03','Trades'),('M04','Services and clocks'),('M05','Users and roles'),('T01','Workers'),('T02','Households'),('T03','Household members'),('T04','Employers'),('T05','Worksites'),('T06','Vacancies'),('T07','Job-mela event'),('T08','Job-mela candidates'),('T09','S2 visit roster and scripted actions'),('T10','Referrals'),('T11','Grievances'),('T12','Training batches'),('T13','Counsellors'),('T14','Counselling cases'),('S_Personas','Eight demonstration people'),('S_MIS_Queries','Five MIS questions'),('S_Mock_API_Behaviour','Expected simulated API responses')]
troubles=terms('If you get stuck',[
('Cannot see a menu?','Use the account listed for the step; each role has different access.'),('Household autofill?','Use the persona helper in Personal & work details first, then Fill P-01/P-03 household. New mandatory C1 fields must also be answered.'),('No seat callback?','Create the SK-01 referral first; already-confirmed cases disappear from the awaiting-seat list.'),('No sync?','Download the visit online, capture offline, then turn Airplane mode off. Keep the same tab for field-device work.'),('Already used a person?','Existing registrations can trigger duplicates. Continue the saved run or intentionally start a fresh rehearsal via Reset; reset clears changes.'),('No acknowledgement dialog?','Use Gateway and the existing case records. Do not repeat the referral submission merely to recreate the dialog.'),
])
page('REFERENCE','Full code directory','Additional catalogue codes that may appear while you navigate. Only the five stage workflows are required for this script.',cols(terms('All 22 software modules',module_items),terms('All 23 service codes',services),terms('All 22 source sheets',sheets)+troubles,cls='directory')+p('<b>Source:</b> local Demo Tools script and current screen handlers (js/demo/script.js, tools.js, auth.js and views-*.js), dataset v1.0 CSV sheets and data/modules.json. Prepared 16 October 2026. This describes the local prototype; mock API calls/messages are simulated.','source'),'compact')

